import { useState, useEffect } from "react";

export const useTabBarManager = (
  defaultValue: string | undefined,
  rememberActiveTab: boolean,
  uniqueId: string | undefined,
  onValueChange: ((value: string) => void) | undefined,
  addTabId?: string,
) => {
  const [activeTab, setActiveTabState] = useState<string>(defaultValue ?? "");

  useEffect(() => {
    if (rememberActiveTab && uniqueId) {
      const storedActiveTab = localStorage.getItem(`${uniqueId}-activeTab`);
      if (storedActiveTab) {
        setActiveTabState(storedActiveTab);
      }
    } else if (uniqueId) {
      localStorage.removeItem(`${uniqueId}-activeTab`);
    }
  }, [rememberActiveTab, uniqueId]);

  const setActiveTab = (value: string) => {
    if (!value || value === addTabId) return;
    setActiveTabState(value);
    if (rememberActiveTab && uniqueId) {
      localStorage.setItem(`${uniqueId}-activeTab`, value);
    }
    onValueChange?.(value);
  };

  return { activeTab, setActiveTab };
};
